// 1. Numeric Enum (auto-increments from 0)
enum Direction {
  Up,    // 0
  Down,  // 1
  Left,  // 2
  Right  // 3
}

// 2. String Enum (explicit string mapping)
enum LogLevel {
  Info = "INFO",
  Warn = "WARN",
  Error = "ERROR",
  Debug = "DEBUG"
}

function writeLog(level: LogLevel, msg: string): void {
  console.log(`[${level}]: ${msg}`);
}

writeLog(LogLevel.Info, "System initialized");
// Output: [INFO]: System initialized

interface UserProfile {
  id: string;
  name: string;
  email: string;
  bio?: string;
}

// Partial<T> marks all properties in T as optional (?)
function updateUserProfile(id: string, patch: Partial<UserProfile>): void {
  console.log(`Updating profile ${id} with:`, patch);
}

// Caller can pass any subset of properties
updateUserProfile("u_101", { bio: "Software Engineer & Open Source Enthusiast" });

// Required<T> does the exact opposite: removes optionality from all properties
type CompleteUserProfile = Required<UserProfile>;

interface AppSettings {
  theme: string;
  version: string;
}

// Readonly<T> marks every property as readonly
const productionSettings: Readonly<AppSettings> = {
  theme: "dark",
  version: "2.4.0"
};

// Reading is permitted
console.log(productionSettings.theme);

// INVALID: Compile-time error
// productionSettings.theme = "light";
// Error: Cannot assign to 'theme' because it is a read-only property.

type Role = "admin" | "editor" | "viewer";

// Record<Keys, ValueType> maps each key in K to type T
const rolePermissions: Record<Role, string[]> = {
  admin: ["create", "read", "update", "delete"],
  editor: ["create", "read", "update"],
  viewer: ["read"]
};

console.log("Admin permissions:", rolePermissions["admin"]);

interface UserAccount {
  id: string;
  username: string;
  email: string;
  passwordHash: string;
  mfaSecret: string;
}

// 1. Pick<T, K>: Selects ONLY the designated keys from T
type PublicUserPreview = Pick<UserAccount, "id" | "username">;

// 2. Omit<T, K>: Removes the designated keys from T
type SafeUserRecord = Omit<UserAccount, "passwordHash" | "mfaSecret">;

const publicProfile: PublicUserPreview = {
  id: "usr_55",
  username: "charlie"
};

console.log(publicProfile);

type AllFileTypes = "pdf" | "docx" | "png" | "jpg" | "exe" | "sh";

// Exclude<T, U>: Excludes from T all union members that are assignable to U
type SafeDocTypes = Exclude<AllFileTypes, "exe" | "sh">;
// SafeDocTypes is "pdf" | "docx" | "png" | "jpg"

// Extract<T, U>: Extracts from T all union members that ARE assignable to U
type ImageTypes = Extract<AllFileTypes, "png" | "jpg" | "svg">;
// ImageTypes is "png" | "jpg"

const upload: ImageTypes = "png";
console.log("Uploaded format:", upload);
